/// batch loses that stream's suffix. There is no implicit queue or transport.
/// Owned deliveries are boxed to keep this control result constant-size; moving
/// a delivery never clones the reader, history, or source scene.

await setup();
await page.evaluate(()=>{autoCanvas.renderer.seekDirect(0.99);autoCanvas.renderer.setPreparedPlaying(true);autoCanvas.renderer.render();});
await start();
const overlap=await page.waitForFunction(()=>{
 const state=JSON.parse(autoCanvas.renderer.debugPreparedPlaybackJson());
 const receipt=JSON.parse(autoCanvas.renderer.debugPointerPresentationJson());
 if(!autoCanvas.producer.producerAlive() || state.time<=1.02 || receipt.presented!==receipt.current) return false;
 const observation={time:state.time,frontier:state.frontier,turns:autoCanvas.producer.turns(),presentedFrames:autoCanvas.driver.stats().presentedFrames};
 // Stop in the same host task as the observation: runner latency must not
 // race source completion before the cancellation assertion below.
 autoCanvas.driver.stopPreparation();autoCanvas.renderer.setPreparedPlaying(false);
 autoCanvas.renderer.seekDirect(0);autoCanvas.driver.wake();
 return observation;
});
result.overlap=await overlap.jsonValue();await overlap.dispose();
assert.ok(result.overlap.frontier>result.overlap.time);assert.ok(result.overlap.turns>0 && result.overlap.turns<49);
assert.ok(result.overlap.presentedFrames>0);
result.checks.push("presented-animated-playback-while-source-active");
